NativeSignal ff_dispatch(VM& vm, Thread& thread) {
    const uint8_t selector = vm.current_native_sub();
    if (selector == 0xF0U) {
        const uint32_t path_address = thread.stack.pop();
        const uint32_t prefix_address = thread.stack.pop();
        const uint32_t index = thread.stack.pop();
        if (index >= 0xF0U || path_address == 0) {
            std::ostringstream message;
            message << "FF:0xF0 invalid module arguments index=" << index
                    << " prefix=0x" << std::hex << std::uppercase
                    << prefix_address << " file=0x" << path_address;
            throw std::runtime_error(message.str());
        }
        const std::string prefix =
            prefix_address == 0
                ? std::string()
                : vm.memory().read_cstring(prefix_address, thread.base);
        const std::string path =
            vm.memory().read_cstring(path_address, thread.base);
        if (!vm.load_module(index, prefix, path)) {
            throw std::runtime_error(
                "FF:0xF0 module load failed: " +
                (prefix.empty() ? path : prefix + ":" + path));
        }
        return NativeSignal::Continue;
    }
    if (selector == 0xF1U) {
        if (!vm.release_module(thread.stack.pop())) {
            throw std::runtime_error("FF:0xF1 unknown module slot");
        }
        return NativeSignal::Continue;
    }
    if (selector == 0xF8U) {
        if (!vm.return_mediated_module()) {
            throw std::runtime_error(
                "FF:0xF8 mediated module stack is empty");
        }
        return NativeSignal::Continue;
    }
    if (selector < 0xF0U) {
        if (debug_trace(DebugTrace::Display)) {
            const auto& module = vm.module(selector);
            std::cout << "FF_MODULE slot=" << selector
                      << " loaded=" << (module.has_value() ? 1 : 0);
            if (module) std::cout << " path=" << module->path
                                  << " bytes=" << module->bytes.size();
            std::cout << '\n';
        }
        if (!vm.execute_module(selector)) {
            std::ostringstream message;
            message << "FF:" << std::hex << std::uppercase
                    << static_cast<unsigned>(selector)
                    << " module slot is missing";
            throw std::runtime_error(message.str());
        }
        return NativeSignal::Continue;
    }
    std::ostringstream message;
    message << "unsupported FF selector 0x" << std::hex
            << std::uppercase << static_cast<unsigned>(selector);
    throw std::runtime_error(message.str());
}
